$id=(int)($_GET['id']??$_POST['id']??0);$st=$pdo->prepare('SELECT * FROM bevetesek WHERE id=?');$st->execute([$id]);$existing=$st->fetch();if(!$existing)exit('A bevetés nem található.');$riasztasId=(int)$existing['riasztas_id'];$hiba='';$siker='';
